#!/usr/bin/env python3
"""Regenerates Adk.Analyzer/AvaloniaMembers.cs from a local Avalonia checkout.

Usage: tools/extract-avalonia-members.py <avalonia-checkout>
The generated table lists, per Avalonia class, its base class, the members it declares
(AvaloniaProperty fields, public instance properties and events) and its attached
properties. The ADK analyzers use it to keep ADK a strict Avalonia subset.
"""
import os
import re
import sys

ROOTS = ["src/Avalonia.Base", "src/Avalonia.Controls"]
CLASS = re.compile(r"^\s*(?:public|internal)\s+(?:(?:abstract|sealed|static|partial|unsafe)\s+)*class\s+(\w+)(?:<[^>{]*>)?\s*(?::\s*([\w.]+))?")
FIELD = re.compile(r"public\s+static\s+readonly\s+(?:Styled|Direct)Property<.*>\s+(\w+)Property\s*=")
ATTACHED = re.compile(r"public\s+static\s+readonly\s+AttachedProperty<.*>\s+(\w+)Property\s*=")
EVENT = re.compile(r"^\s*public\s+(?:(?:virtual|override|new)\s+)*event\s+[\w<>\[\]?,.\s]+?\s+(\w+)\s*(?:;|\{|$)")
CLR = re.compile(r"^\s*public\s+(?:(?:virtual|override|new|sealed)\s+)*(?!static|class|event|const|readonly|delegate|abstract)[\w<>\[\]?,.\s]+?\s+(\w+)\s*(?:\{|=>|$)")


def members(lines, start):
    found = set()
    attached = set()
    depth = 0
    for index in range(start, len(lines)):
        line = lines[index]
        if index > start and depth == 1:
            if CLASS.match(line):
                depth += line.count("{") - line.count("}")
                continue
            match = FIELD.search(line)
            if match:
                found.add(match.group(1))
            match = ATTACHED.search(line)
            if match:
                attached.add(match.group(1))
            match = EVENT.match(line)
            if match:
                found.add(match.group(1))
            match = CLR.match(line)
            if match and "(" not in line.split(match.group(1))[0] and " static " not in " " + line:
                body = " ".join(lines[index:index + 3])
                if "{" in body or "=>" in body:
                    found.add(match.group(1))
        depth += line.count("{") - line.count("}")
        if index > start and depth <= 0 and "}" in line:
            break
    return found, attached


def main():
    root = sys.argv[1]
    classes = {}
    for folder in ROOTS:
        for directory, _, files in os.walk(os.path.join(root, folder)):
            for name in files:
                if not name.endswith(".cs"):
                    continue
                with open(os.path.join(directory, name), encoding="utf-8-sig") as handle:
                    lines = handle.read().split("\n")
                for index, line in enumerate(lines):
                    match = CLASS.match(line)
                    if not match:
                        continue
                    entry = classes.setdefault(match.group(1), [None, set(), set()])
                    base = (match.group(2) or "").split(".")[-1]
                    if base and not re.match(r"I[A-Z]", base):
                        entry[0] = entry[0] or base
                    own, attached = members(lines, index)
                    entry[1] |= own
                    entry[2] |= attached
    out = os.path.join(os.path.dirname(__file__), "..", "Adk.Analyzer", "AvaloniaMembers.cs")
    with open(out, "w", encoding="utf-8") as handle:
        handle.write("// <auto-generated>Regenerate with tools/extract-avalonia-members.py.</auto-generated>\n")
        handle.write("namespace Acrux.Generator;\n\ninternal static class AvaloniaMembers\n{\n")
        handle.write("    // Class|Base|Member,Member,...|AttachedProperty,...\n    public static readonly string[] Table =\n    {\n")
        for name in sorted(classes):
            base, own, attached = classes[name]
            handle.write('        "%s|%s|%s|%s",\n' % (name, base or "", ",".join(sorted(own)), ",".join(sorted(attached))))
        handle.write("    };\n}\n")
    print("classes:", len(classes), "->", os.path.normpath(out))


if __name__ == "__main__":
    main()
